@instrument_model_call
async def call_model(messages, provider, model, scenario):
    if scenario == "model_failure":
        raise RuntimeError("Simulated model provider failure")
    if provider == "demo":
        return {"message": offline_response(messages), "model": "offline-rule-engine", "done_reason": "stop"}
    base_url = os.getenv("OLLAMA_BASE_URL", "http://127.0.0.1:11434").rstrip("/")
    async with httpx.AsyncClient(timeout=120) as client:
        response = await client.post(base_url + "/api/chat", json={
            "model": model, "messages": messages, "tools": TOOL_DEFINITIONS,
            "stream": False, "think": False, "keep_alive": "10m",
            "options": {"temperature": 0.2, "num_predict": 512, "num_ctx": 8192},
        })
        response.raise_for_status()
        return response.json()

