def safe_messages(messages):
    rows = []
    for item in list(messages)[-_MAX_MESSAGES:]:
        role = item.get("role", "user") if isinstance(item, dict) else "user"
        if role not in {m.value for m in MessageRole}:
            role = "user"
        content = item.get("content", "") if isinstance(item, dict) else item
        if isinstance(item, dict) and item.get("tool_calls"):
            content = {"content": content, "tool_calls": item["tool_calls"]}
        captured = safe_json(content) if isinstance(content, dict | list) else safe_text(content)
        if len(captured.encode("utf-8")) > _MAX_MESSAGE_BYTES:
            captured = json.dumps({"truncated": True,
                                   "summary": captured.encode("utf-8")[:230].decode("utf-8", errors="ignore")},
                                  ensure_ascii=False, separators=(",", ":"))
        rows.append(Message(role=MessageRole(role), content=captured))
    return rows

